using System;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Runtime.Serialization.Json;
using System.Text;
using System.Text.RegularExpressions;
using System.Xml;
using FlopCommands.Equity;

namespace FlopCommands.Research {
    public static class ResearchFiles {
        public const int MaxBytes=64*1024*1024;
        static readonly CultureInfo Inv=CultureInfo.InvariantCulture;
        static void Need(bool condition,string text){if(!condition)throw new ArgumentException("調査結果："+text);}
        static bool Percent(double value){return !double.IsNaN(value)&&!double.IsInfinity(value)&&value>=0&&value<=100;}
        public static void Validate(ResearchRunResult result){
            Need(result!=null&&result.Schema==1&&Regex.IsMatch(result.Id??"","^[a-f0-9]{32}$"),"形式・IDが不正です。");Need(result.ClassificationVersion==ResearchFeatures.Version&&result.EngineVersion=="pre-action-joint-v1","未対応の計算・分類版です。");
            ResearchRun.ValidateRequest(result.Catalog,result.ConditionSet,result.Settings);Need(new[]{"completed","completed_with_gaps","cancelled","failed"}.Contains(result.Status),"状態が不正です。");DateTime time;Need(DateTime.TryParse(result.StartedUtc,Inv,DateTimeStyles.RoundtripKind,out time)&&DateTime.TryParse(result.FinishedUtc,Inv,DateTimeStyles.RoundtripKind,out time),"日時が不正です。");
            var planned=result.Catalog.Spots.Where(s=>!result.Settings.AhiOnly||ResearchFeatures.From(s.Board).Aces>0).ToArray();Need(result.TargetSpots==planned.Length&&result.FilteredSpots==result.Catalog.Spots.Count-planned.Length,"対象数が一致しません。");Need(result.Rows!=null&&result.Rows.Count<=10000&&result.ElapsedMs>=0&&!double.IsInfinity(result.ElapsedMs),"行数または時間が不正です。");
            int conditionCount=result.ConditionSet.Conditions.Count(c=>c.Enabled);Need(result.CompletedSpots>=0&&result.CompletedSpots<=result.TargetSpots&&result.Rows.Count==result.CompletedSpots*conditionCount,"確定済みボード数が一致しません。");
            Need(result.Rows.Select(r=>r==null?null:r.SpotId+":"+r.ConditionId).Distinct().Count()==result.Rows.Count,"結果行が重複しています。");
            foreach(var row in result.Rows){Need(row!=null,"空の行があります。");var spot=planned.SingleOrDefault(s=>s.Id==row.SpotId);Need(spot!=null&&row.Board==ResearchValidation.Board(spot.Board)&&row.Node==spot.Node.Trim(),"元ボードと一致しません。");var condition=ResearchValidation.Resolve(result.ConditionSet,spot.Board).SingleOrDefault(c=>c.Id==row.ConditionId);Need(condition!=null&&condition.Label==row.Label&&condition.Syntax==row.Syntax,"使用syntaxが一致しません。");
                var features=ResearchFeatures.From(row.Board);Need(row.Features!=null&&row.Features.Suit==features.Suit&&row.Features.Pair==features.Pair&&row.Features.Aces==features.Aces&&row.Features.High==features.High&&row.Features.Middle==features.Middle&&row.Features.Low==features.Low&&row.Features.OtherRanks==features.OtherRanks,"分類が一致しません。");
                Need(new[]{"completed","frequency_only","no_matching_hands","missing_definition","equity_unavailable","failed"}.Contains(row.Status),"行の状態が不正です。");Need(row.SelectedHands>=0&&(!row.RangePercent.HasValue||Percent(row.RangePercent.Value)),"ハンド数・割合が不正です。");
                var keys=spot.Actions.Select(ResearchRun.ActionKey).Concat(new[]{ResearchRun.TotalBet}).ToArray();Need(row.Actions!=null&&row.Actions.Count==keys.Length&&row.Actions.All(a=>a!=null)&&row.Actions.Select(a=>a.Key).SequenceEqual(keys),"アクションが一致しません。");
                for(int a=0;a<spot.Actions.Count;a++)Need(row.Actions[a].Label==spot.Actions[a].Label&&row.Actions[a].SourcePath==spot.Actions[a].Source.Path,"CSVの出典が一致しません。");
                Need(row.Actions.All(a=>!a.Frequency.HasValue||Percent(a.Frequency.Value)),"頻度が不正です。");bool frequency=row.Actions.All(a=>a.Frequency.HasValue);Need(frequency||row.Actions.All(a=>!a.Frequency.HasValue),"一部だけ頻度が保存されています。");
                if(frequency){Need(Math.Abs(row.Actions.Take(spot.Actions.Count).Sum(a=>a.Frequency.Value)-100)<1e-6,"頻度の合計が100%ではありません。");Need(Math.Abs(row.Actions.Last().Frequency.Value-spot.Actions.Select((a,i)=>a.Kind=="bet"?row.Actions[i].Frequency.Value:0).Sum())<1e-6,"総ベット頻度が不正です。");}
                var eq=row.Equity;if(eq!=null){Need(eq.CalculationVersion=="pre-action-joint-v1"&&!eq.Exact&&eq.Total==result.Settings.Trials&&eq.HeroCount>0&&eq.VillainCount>0&&eq.LegalPairs>0,"EQの情報が不正です。");Need(new[]{eq.Equity,eq.VillainEquity,eq.Win,eq.Tie,eq.Loss,eq.CiLow,eq.CiHigh}.All(Percent)&&eq.CiLow<=eq.Equity&&eq.CiHigh>=eq.Equity&&Math.Abs(eq.Equity+eq.VillainEquity-100)<1e-6,"EQの数値が不正です。");}
                Need((row.Status=="completed")== (eq!=null),"EQと状態が一致しません。");Need(frequency==(row.Status=="completed"||row.Status=="frequency_only"||row.Status=="equity_unavailable"),"頻度と状態が一致しません。");Need((row.Status=="missing_definition")== (condition.Status=="missing_definition"),"未設定状態が一致しません。");
            }
            Need(result.Rows.Select(r=>r.SpotId).Distinct().Count()==result.CompletedSpots,"ボードの確定単位が不正です。");
            foreach(var g in result.Rows.GroupBy(r=>r.SpotId))Need(g.Count()==conditionCount,"ボードの条件が不完全です。");
            if(result.Status=="completed"||result.Status=="completed_with_gaps")Need(result.CompletedSpots==result.TargetSpots,"未完了のボードがあります。");
        }
        sealed class LimitedStream : MemoryStream {
            public override void Write(byte[] buffer,int offset,int count){if(Position+count>MaxBytes)throw new ArgumentException("調査結果は64MiB以下にしてください。");base.Write(buffer,offset,count);}
            public override void WriteByte(byte value){if(Position>=MaxBytes)throw new ArgumentException("調査結果は64MiB以下にしてください。");base.WriteByte(value);}
        }
        static DataContractJsonSerializer Serializer(){return new DataContractJsonSerializer(typeof(ResearchRunResult),new DataContractJsonSerializerSettings{UseSimpleDictionaryFormat=true,MaxItemsInObjectGraph=2000000});}
        public static byte[] Encode(ResearchRunResult result){Validate(result);using(var stream=new LimitedStream()){Serializer().WriteObject(stream,result);if(stream.Length>MaxBytes)throw new ArgumentException("調査結果JSONは64MiB以下にしてください。");return stream.ToArray();}}
        public static ResearchRunResult Decode(byte[] bytes){Need(bytes!=null&&bytes.Length<=MaxBytes,"JSONが大きすぎます。");using(var stream=new MemoryStream(bytes)){var result=(ResearchRunResult)Serializer().ReadObject(stream);Validate(result);return result;}}
        public static ResearchRunResult Read(string path){using(var f=File.OpenRead(path)){Need(f.Length<=MaxBytes,"JSONが大きすぎます。");using(var stream=new MemoryStream()){f.CopyTo(stream);return Decode(stream.ToArray());}}}
        static string Number(double? value){return value.HasValue?value.Value.ToString("R",Inv):"";}
        static string Cell(string value){value=value??"";if(value.TrimStart().Length>0&&"=+-@".IndexOf(value.TrimStart()[0])>=0)value="'"+value;return "\""+value.Replace("\"","\"\"")+"\"";}
        static void Row(StringBuilder b,params string[] values){b.AppendLine(string.Join(",",values.Select(Cell)));}
        public static byte[] Csv(ResearchRunResult result){Validate(result);var b=new StringBuilder();Row(b,"scope","group_or_board","node","condition_id","condition","syntax","action_key","action_label","frequency_percent","eq_percent","range_percent","selected_hands","target_spots","available_action_spots","frequency_n","paired_n","paired_frequency","paired_eq","min_frequency","max_frequency","ci_low","ci_high","status","reason","source_csv","spot_ids","seed");
            foreach(var r in result.Rows)foreach(var a in r.Actions)Row(b,"board",r.Board,r.Node,r.ConditionId,r.Label,r.Syntax,a.Key,a.Label,Number(a.Frequency),Number(r.Equity==null?(double?)null:r.Equity.Equity),Number(r.RangePercent),r.SelectedHands.ToString(Inv),"1","1",a.Frequency.HasValue?"1":"0",r.Equity!=null&&a.Frequency.HasValue?"1":"0","","","","",Number(r.Equity==null?(double?)null:r.Equity.CiLow),Number(r.Equity==null?(double?)null:r.Equity.CiHigh),r.Status,r.Reason,a.SourcePath,r.SpotId,r.Equity==null?"":r.Equity.Seed.ToString(Inv));
            foreach(var s in ResearchRun.Summaries(result))Row(b,"category",s.Group,"",s.ConditionId,s.Label,"",s.ActionKey,s.Action,Number(s.FrequencyMean),Number(s.EquityMean),Number(s.RangeMean),"",s.Target.ToString(Inv),s.Available.ToString(Inv),s.FrequencyCount.ToString(Inv),s.PairedCount.ToString(Inv),Number(s.PairedFrequency),Number(s.PairedEquity),Number(s.FrequencyMin),Number(s.FrequencyMax),"","",result.Status,"登録された有効ボードの等重み平均。paired列は同一対象。","",string.Join(";",s.FrequencySpots),result.Settings.Seed.ToString(Inv));
            return new UTF8Encoding(true).GetPreamble().Concat(Encoding.UTF8.GetBytes(b.ToString())).ToArray();
        }
        static string Md(string s){return (s??"").Replace("\\","\\\\").Replace("|","\\|").Replace("\r"," ").Replace("\n"," ").Replace("<","&lt;").Replace(">","&gt;");}
        static string Short(double? n){return n.HasValue?n.Value.ToString("0.00",Inv):"—";}
        public static byte[] Markdown(ResearchRunResult r){Validate(r);var b=new StringBuilder();b.AppendLine("# ボード別戦略調査\n");b.AppendLine("カタログ："+Md(r.Catalog.Name)+"（版 "+r.Catalog.Revision+"） / 条件セット："+Md(r.ConditionSet.Name)+"（版 "+r.ConditionSet.Revision+"）\n");b.AppendLine("状態："+r.Status+" / 確定 "+r.CompletedSpots+" / 対象 "+r.TargetSpots+" / 対象外 "+r.FilteredSpots+"。"+Md(r.Error)+"\n");b.AppendLine("自分 "+Md(r.Catalog.Scenario.HeroPosition)+" vs "+Md(r.Catalog.Scenario.VillainPosition)+" / "+Md(r.Catalog.Scenario.StackBb)+"bb / "+Md(r.Catalog.Scenario.PotType)+" / EQ基準点："+Md(r.Catalog.Scenario.EquityReference)+"\n");b.AppendLine("アクション履歴："+Md(r.Catalog.Scenario.ActionHistory)+" / 設定："+Md(r.Catalog.Scenario.SolutionContext)+"\n");b.AppendLine("分類："+r.Settings.GroupBy+" / "+r.ClassificationVersion+" / 試行数（各条件）："+r.Settings.Trials+" / 基準シード："+r.Settings.Seed+"\n");
            b.AppendLine("カテゴリは登録された有効ボードの等重み平均。欠損は0に置換せず、アクション位置ごとに分けます。EQと頻度が両方ある同じ対象だけが散布図に入ります。全Ahiボードの母集団を代表するとは限りません。\n");b.AppendLine("| 分類・アクション位置 | 条件 | アクション | 頻度平均% | 最小–最大% | 頻度有効/対象 | EQ平均% | EQ有効 |\n| --- | --- | --- | ---: | --- | --- | ---: | ---: |");foreach(var s in ResearchRun.Summaries(r))b.AppendLine("| "+Md(s.Group)+" | "+Md(s.Label)+" | "+Md(s.Action)+" | "+Short(s.FrequencyMean)+" | "+Short(s.FrequencyMin)+"–"+Short(s.FrequencyMax)+" | "+s.FrequencyCount+"/"+s.Target+" | "+Short(s.EquityMean)+" | "+s.EquityCount+" |");
            b.AppendLine("\n## ボード別の条件と結果\n");foreach(var row in r.Rows){b.AppendLine("- "+Md(row.Board+" / "+row.Node+" / "+row.Label)+"："+row.Status+" / EQ "+Short(row.Equity==null?(double?)null:row.Equity.Equity)+"% / レンジ内 "+Short(row.RangePercent)+"% / "+Md(row.Reason));b.AppendLine("  syntax： "+Md(row.Syntax));foreach(var a in row.Actions)b.AppendLine("  "+Md(a.Label)+"："+Short(a.Frequency)+"%");}
            b.AppendLine("\n## 入力の出典\n");foreach(var spot in r.Catalog.Spots){b.AppendLine("- "+Md(spot.Board+" / "+spot.Node));foreach(var s in spot.Actions.Select(a=>a.Source).Concat(spot.Opponents))b.AppendLine("  "+Md(s.Path)+" / SHA-256 "+s.Sha256);}return Encoding.UTF8.GetBytes(b.ToString());
        }
        public static string[] ActionKeys(ResearchRunResult r){return r.Catalog.Spots.SelectMany(s=>s.Actions.Select(ResearchRun.ActionKey)).Distinct().OrderBy(k=>k,StringComparer.Ordinal).ToArray();}
        public static string Color(string key,string[] keys){int i=Array.IndexOf(keys,key);string[] palette={"#2563eb","#008470","#b45309","#9333ea","#db2777","#0e7490","#6d7c12","#c2410c"};if(keys.Length<=palette.Length)return palette[Math.Max(0,i)];double h=(Math.Max(i,0)*360.0/keys.Length)/60,c=.65,x=c*(1-Math.Abs(h%2-1)),m=.18;double[] rgb=h<1?new[]{c,x,0}:h<2?new[]{x,c,0}:h<3?new[]{0,c,x}:h<4?new[]{0,x,c}:h<5?new[]{x,0,c}:new[]{c,0,x};return "#"+string.Concat(rgb.Select(v=>((int)Math.Round((v+m)*255)).ToString("x2",Inv)));}
        static string N(double v){return v.ToString("0.###",Inv);}
        static void Element(XmlWriter w,string tag,params string[] attributes){w.WriteStartElement(tag);for(int i=0;i<attributes.Length;i+=2)w.WriteAttributeString(attributes[i],attributes[i+1]);w.WriteEndElement();}
        static void Text(XmlWriter w,double x,double y,string value){w.WriteStartElement("text");w.WriteAttributeString("x",N(x));w.WriteAttributeString("y",N(y));w.WriteString(value);w.WriteEndElement();}
        public static byte[] Svg(ResearchRunResult r,bool grouped){Validate(r);var points=ResearchRun.Points(r,grouped);if(points.Length==0)throw new ArgumentException("EQと頻度が揃った点がありません。表またはCSVで欠損理由を確認してください。");var keys=ActionKeys(r);int legendRows=(keys.Length+2)/3,top=105+legendRows*26,height=top+540;using(var stream=new LimitedStream()){using(var w=XmlWriter.Create(stream,new XmlWriterSettings{Encoding=new UTF8Encoding(false),Indent=true})){w.WriteStartElement("svg","http://www.w3.org/2000/svg");w.WriteAttributeString("viewBox","0 0 1100 "+height);w.WriteAttributeString("font-family","sans-serif");w.WriteAttributeString("font-size","14");w.WriteElementString("title","EQ × Action frequency — "+(grouped?"group averages":"per board"));Element(w,"rect","width","1100","height",height.ToString(Inv),"fill","white");Text(w,50,28,r.Catalog.Name+" / "+r.Status+" / "+r.CompletedSpots+" of "+r.TargetSpots+" spots");Text(w,50,50,grouped?"Equal-weight averages of the same paired observations; no group confidence interval.":"Board-level estimates; horizontal bars show Monte Carlo 95% intervals.");for(int i=0;i<keys.Length;i++){double x=50+(i%3)*345,y=78+(i/3)*26;Element(w,"rect","x",N(x),"y",N(y-12),"width","12","height","12","fill",Color(keys[i],keys));Text(w,x+19,y,ResearchRun.ActionLabel(keys[i]));}
                    for(int n=0;n<=100;n+=20){double x=80+9.5*n,y=top+420-4.2*n;Element(w,"line","x1",N(x),"x2",N(x),"y1",N(top),"y2",N(top+420),"stroke","#e1e8ee");Element(w,"line","x1","80","x2","1030","y1",N(y),"y2",N(y),"stroke","#e1e8ee");Text(w,x-8,top+444,n.ToString(Inv));Text(w,40,y+5,n.ToString(Inv));}Text(w,80,top-12,"Action frequency (%)");Text(w,450,top+477,"Pre-action EQ (%)");
                    foreach(var p in points)if(p.CiLow.HasValue){double y=top+420-4.2*p.Frequency;Element(w,"line","x1",N(80+9.5*p.CiLow.Value),"x2",N(80+9.5*p.CiHigh.Value),"y1",N(y),"y2",N(y),"stroke",Color(p.ActionKey,keys),"stroke-width","2","opacity","0.4");}
                    foreach(var group in points.GroupBy(p=>new{p.Equity,p.Frequency})){double x=80+9.5*group.Key.Equity,y=top+420-4.2*group.Key.Frequency;var actionKeys=group.Select(p=>p.ActionKey).Distinct().ToArray();w.WriteStartElement("g");w.WriteElementString("title",string.Join("\n\n",group.Select(p=>p.Label+" | "+p.Syntax+" | "+p.Action+" | EQ "+N(p.Equity)+"% | Frequency "+N(p.Frequency)+"% | "+p.Details)));
                        if(actionKeys.Length==1)Element(w,"circle","cx",N(x),"cy",N(y),"r","6","fill",Color(actionKeys[0],keys));
                        else for(int i=0;i<actionKeys.Length;i++){double a=2*Math.PI*i/actionKeys.Length,b=2*Math.PI*(i+1)/actionKeys.Length;Element(w,"path","d","M "+N(x)+","+N(y)+" L "+N(x+6*Math.Cos(a))+","+N(y+6*Math.Sin(a))+" A 6,6 0 0,1 "+N(x+6*Math.Cos(b))+","+N(y+6*Math.Sin(b))+" Z","fill",Color(actionKeys[i],keys));}
                        Element(w,"circle","cx",N(x),"cy",N(y),"r","6","fill","none","stroke","white");w.WriteEndElement();}
                    Text(w,50,top+515,"Hover points for condition and source details. Missing values are not plotted as zero.");w.WriteEndElement();}return stream.ToArray();}}
        public static void Export(ResearchRunResult r,string path,string extension,bool grouped,string protectedSettingsPath){Validate(r);string full=Path.GetFullPath(path);Need(string.Equals(Path.GetExtension(full),extension,StringComparison.OrdinalIgnoreCase),"保存先の拡張子が異なります。");foreach(var source in r.Catalog.Spots.SelectMany(s=>s.Actions.Select(a=>a.Source.Path).Concat(s.Opponents.Select(a=>a.Path))).Concat(new[]{protectedSettingsPath})){if(!string.IsNullOrEmpty(source))Need(!string.Equals(full,Path.GetFullPath(source),StringComparison.OrdinalIgnoreCase),"入力ファイルや設定ファイルへは上書きできません。");}byte[] bytes=extension==".json"?Encode(r):extension==".csv"?Csv(r):extension==".svg"?Svg(r,grouped):extension==".md"?Markdown(r):null;Need(bytes!=null,"未対応の出力形式です。");EquityFiles.WriteAtomic(full,bytes,true);}
        public static string SaveHistory(ResearchRunResult result,string root){Directory.CreateDirectory(root);string path=Path.Combine(root,result.Id+".json");EquityFiles.WriteAtomic(path,Encode(result),false);return path;}
    }
}
